import json
import os
import tempfile
import xml.etree.ElementTree as ET

import framework_evidence

SCOPE = "192.168.0.0/16"
EXCLUDED = "192.168.122.1"
NETWORK_CONTEXT = {
    "interface": "eth0",
    "interface_address": "192.168.0.5/16",
    "route_to_scope": "192.168.0.0/16 dev eth0",
    "default_route": "via 192.168.0.1 dev eth0",
    "source": "task-provided execution_environment.network_facts",
}


def strings_in(value):
    """Yield strings from a tool envelope without assuming its exact shape."""
    if isinstance(value, str):
        yield value
    elif isinstance(value, dict):
        for item in value.values():
            yield from strings_in(item)
    elif isinstance(value, (list, tuple)):
        for item in value:
            yield from strings_in(item)


def extract_nmap_xml(envelope):
    for text in strings_in(envelope):
        start = text.find("<?xml")
        if start < 0:
            start = text.find("<nmaprun")
        if start >= 0:
            candidate = text[start:]
            end = candidate.find("</nmaprun>")
            if end >= 0:
                return candidate[:end + len("</nmaprun>")]
    return None


def run(argv):
    try:
        return framework_evidence.run_tool(argv), None
    except Exception as exc:
        return None, {"error": type(exc).__name__, "message": str(exc), "argv": argv}


report = {
    "scope": SCOPE,
    "excluded_address": EXCLUDED,
    "exclusion_requested_in_each_scan": True,
    "network_context": NETWORK_CONTEXT,
    "discovery": None,
    "discovered_hosts": [],
    "discovery_parse_status": "not_attempted",
    "port_scan": None,
    "port_scan_coverage_requested": {
        "protocols": ["TCP", "UDP"],
        "ports_per_protocol": "1-65535",
        "service_detection": "Nmap version detection enabled for detected open ports",
    },
    "limitations": [],
}

# Nmap performs the parallel host-discovery probes over the complete requested range.
discovery_argv = [
    "nmap", "-sn", "-n", "-T4", "--exclude", EXCLUDED, "-oX", "-", SCOPE
]
discovery, discovery_error = run(discovery_argv)
if discovery_error:
    report["discovery"] = {"execution_error": discovery_error, "argv": discovery_argv}
    report["discovery_parse_status"] = "unavailable_due_to_execution_error"
    report["limitations"].append("Host discovery did not return a tool envelope; candidate coverage is unknown.")
else:
    report["discovery"] = discovery
    xml_text = extract_nmap_xml(discovery)
    if xml_text is None:
        report["discovery_parse_status"] = "nmap_xml_not_found_in_tool_envelope"
        report["limitations"].append("Could not find raw Nmap XML in the discovery envelope; hosts were not inferred.")
    else:
        try:
            root = ET.fromstring(xml_text)
            hosts = []
            for host in root.findall("host"):
                status = host.find("status")
                if status is None or status.get("state") != "up":
                    continue
                for addr in host.findall("address"):
                    if addr.get("addrtype") == "ipv4":
                        address = addr.get("addr")
                        if address and address != EXCLUDED:
                            hosts.append(address)
                        break
            report["discovered_hosts"] = sorted(set(hosts), key=lambda x: tuple(int(p) for p in x.split(".")))
            report["discovery_parse_status"] = "parsed"
            if EXCLUDED in report["discovered_hosts"]:
                report["discovered_hosts"].remove(EXCLUDED)
                report["limitations"].append("Excluded address appeared in parsed discovery output and was filtered before port scanning.")
        except Exception as exc:
            report["discovery_parse_status"] = "xml_parse_error"
            report["discovery_parse_error"] = {"error": type(exc).__name__, "message": str(exc)}
            report["limitations"].append("Discovery XML could not be parsed; no candidate list was used for port scanning.")

if report["discovered_hosts"]:
    try:
        # A target file avoids operating-system argument-size limits for large candidate sets.
        with tempfile.NamedTemporaryFile(mode="w", encoding="ascii", prefix="nmap_targets_", delete=False) as target_file:
            target_path = target_file.name
            target_file.write("\n".join(report["discovered_hosts"]) + "\n")
        scan_argv = [
            "nmap", "-n", "-Pn", "-T4", "--exclude", EXCLUDED,
            "-sS", "-sU", "-sV", "--version-light",
            "-p", "T:1-65535,U:1-65535", "--reason", "-oX", "-",
            "-iL", target_path,
        ]
        scan, scan_error = run(scan_argv)
        if scan_error:
            report["port_scan"] = {"execution_error": scan_error, "argv": scan_argv}
            report["limitations"].append("The all-port TCP/UDP scan did not return a tool envelope; port coverage is unknown.")
        else:
            report["port_scan"] = scan
            scan_xml = extract_nmap_xml(scan)
            if scan_xml is None:
                report["port_scan_parse_status"] = "nmap_xml_not_found_in_tool_envelope"
                report["limitations"].append("Could not find raw Nmap XML in the port-scan envelope; service and port results were not parsed.")
            else:
                try:
                    scan_root = ET.fromstring(scan_xml)
                    parsed_hosts = []
                    for host in scan_root.findall("host"):
                        addresses = [a.get("addr") for a in host.findall("address") if a.get("addrtype") == "ipv4"]
                        ports = []
                        port_container = host.find("ports")
                        if port_container is not None:
                            for port in port_container.findall("port"):
                                state = port.find("state")
                                service = port.find("service")
                                ports.append({
                                    "protocol": port.get("protocol"),
                                    "port": port.get("portid"),
                                    "state": state.get("state") if state is not None else None,
                                    "reason": state.get("reason") if state is not None else None,
                                    "service": service.attrib if service is not None else None,
                                })
                        parsed_hosts.append({"addresses": addresses, "ports_reported": ports})
                    runstats = scan_root.find("runstats")
                    report["port_scan_parse_status"] = "parsed"
                    report["port_scan_parsed_hosts"] = parsed_hosts
                    report["port_scan_runstats"] = ET.tostring(runstats, encoding="unicode") if runstats is not None else None
                    report["all_requested_ports_examined"] = "not established from XML alone; assess raw envelope, host completion and run statistics"
                except Exception as exc:
                    report["port_scan_parse_status"] = "xml_parse_error"
                    report["port_scan_parse_error"] = {"error": type(exc).__name__, "message": str(exc)}
                    report["limitations"].append("Port-scan XML could not be parsed; raw tool envelope is retained for assessment.")
    except Exception as exc:
        report["port_scan"] = {"preparation_error": type(exc).__name__, "message": str(exc)}
        report["limitations"].append("Could not prepare or invoke the candidate all-port scan; coverage is incomplete.")
    finally:
        if "target_path" in locals():
            try:
                os.unlink(target_path)
            except OSError as exc:
                report["limitations"].append("Temporary target-list cleanup failed: " + str(exc))
else:
    report["port_scan_parse_status"] = "not_run_no_parsed_discovery_hosts"
    if report["discovery_parse_status"] == "parsed":
        report["limitations"].append("No hosts were reported up in the parsed discovery output; port scans were not run.")

print(json.dumps(report, ensure_ascii=False, separators=(",", ":")))

