import concurrent.futures
import json
import sys

import framework_evidence

TARGET = "192.168.3.3"
EXCLUDED = "192.168.122.1"


def scan(protocol):
    if TARGET == EXCLUDED:
        raise RuntimeError("Refusing to scan the explicitly excluded address")

    if protocol == "tcp":
        mode = "-sS"
    elif protocol == "udp":
        mode = "-sU"
    else:
        raise ValueError("Unsupported protocol: " + protocol)

    argv = [
        "nmap",
        "-n",
        "-Pn",
        mode,
        "-p",
        "1-65535",
        "-sV",
        "--version-light",
        "--reason",
        "-T4",
        "--min-rate",
        "1000",
        "--max-retries",
        "2",
        "-oX",
        "-",
        TARGET,
    ]
    try:
        envelope = framework_evidence.run_tool(argv)
        return {"protocol": protocol, "target": TARGET, "argv": argv, "envelope": envelope}
    except Exception as exc:
        return {
            "protocol": protocol,
            "target": TARGET,
            "argv": argv,
            "error": type(exc).__name__ + ": " + str(exc),
        }


def main():
    results = {}
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        futures = {pool.submit(scan, proto): proto for proto in ("tcp", "udp")}
        for future in concurrent.futures.as_completed(futures):
            protocol = futures[future]
            try:
                results[protocol] = future.result()
            except Exception as exc:
                results[protocol] = {
                    "protocol": protocol,
                    "target": TARGET,
                    "error": type(exc).__name__ + ": " + str(exc),
                }

    print(json.dumps({
        "target": TARGET,
        "excluded_address": EXCLUDED,
        "requested_ports_per_protocol": "1-65535",
        "parallel_protocol_scans": True,
        "results": {key: results[key] for key in ("tcp", "udp")},
    }, ensure_ascii=False, default=str))


if __name__ == "__main__":
    main()

