import concurrent.futures
import json
import sys

import framework_evidence

CANDIDATES = [
    "192.168.0.1",
    "192.168.3.3",
    "192.168.0.5",
    "192.168.65.3",
    "192.168.65.6",
]
EXCLUDED = "192.168.122.1"


def run_scan(target, protocol):
    if target == EXCLUDED:
        raise ValueError("explicitly excluded target")

    if protocol == "tcp":
        scan_args = ["-sS", "-p-"]
    else:
        scan_args = ["-sU", "-p-"]

    argv = [
        "nmap", "-n", "-Pn", "-T4", *scan_args,
        "-sV", "--reason", "-oX", "-", target,
    ]
    try:
        envelope = framework_evidence.run_tool(argv)
        return {"target": target, "protocol": protocol, "evidence": envelope}
    except Exception as exc:
        return {
            "target": target,
            "protocol": protocol,
            "error": type(exc).__name__ + ": " + str(exc),
            "argv": argv,
        }


def main():
    jobs = [(target, protocol) for target in CANDIDATES for protocol in ("tcp", "udp")]
    with concurrent.futures.ThreadPoolExecutor(max_workers=len(jobs)) as pool:
        futures = [pool.submit(run_scan, target, protocol) for target, protocol in jobs]
        for future in concurrent.futures.as_completed(futures):
            try:
                record = future.result()
            except Exception as exc:
                record = {"error": type(exc).__name__ + ": " + str(exc)}
            print(json.dumps(record, ensure_ascii=False, default=str), flush=True)


if __name__ == "__main__":
    main()

