import json
from concurrent.futures import ThreadPoolExecutor, as_completed

import framework_evidence

TARGET = "192.168.0.1"
SCANS = {
    "tcp": [
        "nmap", "-n", "-Pn", "-T5", "-sS", "-p-", "-sV", "--reason", "-oX", "-", TARGET
    ],
    "udp": [
        "nmap", "-n", "-Pn", "-T5", "-sU", "-p-", "-sV", "--reason", "-oX", "-", TARGET
    ],
}


def run_scan(protocol, argv):
    try:
        envelope = framework_evidence.run_tool(argv)
        return protocol, envelope
    except Exception as exc:
        return protocol, {
            "status": "error",
            "argv": argv,
            "error_type": type(exc).__name__,
            "error": str(exc),
        }


with ThreadPoolExecutor(max_workers=2) as pool:
    futures = [pool.submit(run_scan, protocol, argv) for protocol, argv in SCANS.items()]
    for future in as_completed(futures):
        protocol, envelope = future.result()
        # Preserve and emit the helper's complete envelope; protocol and requested
        # coverage are labels, not claims about completed scan coverage.
        print(json.dumps({
            "protocol_requested": protocol,
            "target": TARGET,
            "ports_requested": "1-65535",
            "coverage_claim": "requested; assess from the returned execution and parser evidence",
            "tool_result": envelope,
        }, ensure_ascii=False), flush=True)

