def make_request(xid):
    # ONC RPC v2 CALL: portmapper program 100000, version 2, PMAPPROC_DUMP 4.
    return (struct.pack("!IIIIII", xid, 0, 2, 100000, 2, 4)
            + u32(0) + u32(0) + u32(0) + u32(0))


def recv_exact(sock, size):
    chunks = []
    remaining = size
    while remaining:
        part = sock.recv(remaining)
        if not part:
            raise EOFError("peer closed before the complete RPC record arrived")
        chunks.append(part)
        remaining -= len(part)
    return b"".join(chunks)


def read_tcp_record(sock):
    pieces = []
    while True:
        marker = struct.unpack("!I", recv_exact(sock, 4))[0]
        length = marker & 0x7fffffff
        if length > 1048576:
            raise ValueError("RPC record fragment exceeds 1 MiB")
        pieces.append(recv_exact(sock, length))
        if marker & 0x80000000:
            return b"".join(pieces)


def decode_reply(data, expected_xid):
    pos = 0

    def get_u32():
        nonlocal pos
        if pos + 4 > len(data):
            raise ValueError("truncated XDR uint32")
        value = struct.unpack_from("!I", data, pos)[0]
        pos += 4
        return value

    xid = get_u32()
    message_type = get_u32()
    if xid != expected_xid:
        raise ValueError("reply XID does not match request")
    if message_type != 1:
        raise ValueError("RPC message is not a REPLY")
    reply_stat = get_u32()
    if reply_stat != 0:
        return {"rpc_reply": "denied", "reject_status": get_u32(),
                "mappings": []}
    verifier_flavor = get_u32()
    verifier_length = get_u32()
    padded = (verifier_length + 3) & ~3
    if pos + padded > len(data):
        raise ValueError("truncated RPC verifier")
    verifier = data[pos:pos + verifier_length]
    pos += padded
    accept_stat = get_u32()
    if accept_stat != 0:
        return {"rpc_reply": "accepted_but_procedure_failed",
                "verifier_flavor": verifier_flavor,
                "verifier_hex": verifier.hex(),
                "accept_status": accept_stat, "mappings": []}

    mappings = []
    while True:
        present = get_u32()
        if present not in (0, 1):
            raise ValueError("invalid XDR linked-list boolean")
        if not present:
            break
        mappings.append({
            "program": get_u32(),
            "version": get_u32(),
            "transport_number": get_u32(),
            "port": get_u32(),
        })
        if len(mappings) > 4096:
            raise ValueError("registration list exceeds safety bound")
    return {"rpc_reply": "accepted",
            "verifier_flavor": verifier_flavor,
            "verifier_hex": verifier.hex(),
            "mappings": mappings,
            "trailing_bytes": len(data) - pos}


def load_rpc_names():
    names = {}
    path = "/etc/rpc"
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as stream:
            for line in stream:
                line = line.split("#", 1)[0].strip()
                fields = line.split()
                if len(fields) >= 2:
                    try:
                        number = int(fields[1], 10)
                    except ValueError:
                        continue
                    names.setdefault(number, []).append(fields[0])
    except OSError as exc:
        return {}, {"path": path, "error": str(exc)}
    return names, {"path": path, "read": True}


def query_tcp(request, xid):
    with socket.create_connection((HOST, PORT), timeout=TIMEOUT) as sock:
        sock.settimeout(TIMEOUT)
        sock.sendall(struct.pack("!I", 0x80000000 | len(request)) + request)
        return read_tcp_record(sock)


def query_udp(request):
    with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
        sock.settimeout(TIMEOUT)
        sock.sendto(request, (HOST, PORT))
        data, peer = sock.recvfrom(65535)
        return data, peer


def main():
    names, names_source = load_rpc_names()
    results = []
    for transport in ("tcp", "udp"):
        xid = int.from_bytes(os.urandom(4), "big")
        request = make_request(xid)
        item = {"transport": transport, "target": f"{HOST}:{PORT}",
                "procedure": "portmapper v2 DUMP (4)",
                "request_hex": request.hex(), "status": "started"}
        started = time.monotonic()
        try:
            if transport == "tcp":
                reply = query_tcp(request, xid)
                peer = f"{HOST}:{PORT}"
            else:
                reply, address = query_udp(request)
                peer = f"{address[0]}:{address[1]}"
            item["peer"] = peer
            item["raw_reply_hex"] = reply.hex()
            item["reply_bytes"] = len(reply)
            item["decoded"] = decode_reply(reply, xid)
            item["status"] = "completed"
        except Exception as exc:
            item["status"] = "error_or_incomplete"
            item["error_type"] = type(exc).__name__
            item["error"] = str(exc)
        item["elapsed_seconds"] = round(time.monotonic() - started, 3)
        results.append(item)

    for item in results:
        decoded = item.get("decoded")
        if not decoded:
            continue
        for mapping in decoded.get("mappings", []):
            mapping["program_labels_from_local_etc_rpc"] = names.get(
                mapping["program"], [])
            mapping["transport"] = {
                6: "tcp", 17: "udp"}.get(mapping["transport_number"], "unknown")

    output = {
        "target": HOST,
        "scope_note": "Only 192.168.0.1 was queried; 192.168.122.1 was not contacted.",
        "query": "ONC RPC portmapper v2 DUMP; NULL and STAT were not repeated.",
        "rpc_name_source": names_source,
        "results": results,
        "assessment_note": (
            "Registration entries evidence advertised program/version/transport/port "
            "metadata. Local /etc/rpc labels are reference labels, not endpoint "
            "identity. No login procedure or flag is inferred from registration "
            "metadata alone; protocol-specific follow-up requires an identified "
            "login-capable application and supported procedure."
        ),
    }
    print(json.dumps(output, sort_keys=True))


if __name__ == "__main__":
    main()

