import concurrent.futures
import json
import re
import socket
import struct
import sys
import xml.etree.ElementTree as ET

TARGET = "192.168.0.1"
PORT_MIN = 1
PORT_MAX = 65535
BATCH_SIZE = 4096
WORKERS = 16


def emit(value):
    print(json.dumps(value, sort_keys=True, default=repr), flush=True)


def scan_batch(start, end):
    port_range = f"{start}-{end}"
    argv = [
        "nmap", "-sU", "-sV", "--version-intensity", "2", "--reason",
        "-n", "-Pn", "-T4", "--max-retries", "0", "--host-timeout",
        "45s", "-p", port_range, "-oX", "-", TARGET
    ]
    try:
        from framework_evidence import run_tool
        envelope = run_tool(argv)
        return {"range": port_range, "expected_ports": end - start + 1,
                "argv": argv, "envelope": envelope}
    except Exception as exc:
        return {"range": port_range, "expected_ports": end - start + 1,
                "argv": argv, "helper_error": repr(exc)}


def strings_under_stdout(value):
    found = []
    if isinstance(value, dict):
        for key, item in value.items():
            if str(key).lower() == "stdout" and isinstance(item, str):
                found.append(item)
            found.extend(strings_under_stdout(item))
    elif isinstance(value, list):
        for item in value:
            found.extend(strings_under_stdout(item))
    return found


def parse_batch(result):
    info = {"range": result["range"], "expected_ports": result["expected_ports"],
            "covered_ports": 0, "coverage_complete": False,
            "coverage_counts_by_state": {}, "identified_services": [],
            "xml_parse": "not_available"}
    envelope = result.get("envelope")
    streams = strings_under_stdout(envelope)
    xml_text = next((s for s in streams if "<nmaprun" in s), None)
    if xml_text is None:
        info["xml_parse"] = "no_nmap_xml_found_in_tool_stdout"
        return info
    try:
        root = ET.fromstring(xml_text[xml_text.find("<nmaprun"):])
        info["xml_parse"] = "success"
        host = root.find("host")
        if host is None:
            info["host_status"] = "no_host_element"
            return info
        status = host.find("status")
        info["host_status"] = status.get("state") if status is not None else "unknown"
        counts = {}
        ports = host.find("ports")
        if ports is not None:
            for port in ports.findall("port"):
                state_el = port.find("state")
                state = state_el.get("state", "unknown") if state_el is not None else "unknown"
                counts[state] = counts.get(state, 0) + 1
                service = port.find("service")
                if (port.get("protocol") == "udp" and service is not None
                        and service.get("method") == "probed"):
                    info["identified_services"].append({
                        "protocol": "udp",
                        "port": int(port.get("portid")),
                        "name": service.get("name"),
                        "product": service.get("product"),
                        "version": service.get("version"),
                        "tunnel": service.get("tunnel"),
                        "method": service.get("method"),
                        "confidence": service.get("conf")
                    })
            for extra in ports.findall("extraports"):
                state = extra.get("state", "unknown")
                try:
                    count = int(extra.get("count", "0"))
                except ValueError:
                    count = 0
                counts[state] = counts.get(state, 0) + count
        info["coverage_counts_by_state"] = counts
        info["covered_ports"] = sum(counts.values())
        info["coverage_complete"] = info["covered_ports"] == info["expected_ports"]
        return info
    except Exception as exc:
        info["xml_parse"] = "failed"
        info["xml_parse_error"] = repr(exc)
        return info


def ber_length(n):
    if n < 128:
        return bytes([n])
    raw = n.to_bytes((n.bit_length() + 7) // 8, "big")
    return bytes([0x80 | len(raw)]) + raw


def ber(tag, payload):
    return bytes([tag]) + ber_length(len(payload)) + payload


def ber_integer(n):
    raw = n.to_bytes(max(1, (n.bit_length() + 7) // 8), "big", signed=False)
    if raw[0] & 0x80:
        raw = b"\x00" + raw
    return ber(0x02, raw)


def encode_oid(parts):
    values = [40 * parts[0] + parts[1]] + parts[2:]
    out = bytearray()
    for value in values:
        encoded = [value & 0x7f]
        value >>= 7
        while value:
            encoded.append(0x80 | (value & 0x7f))
            value >>= 7
        out.extend(reversed(encoded))
    return ber(0x06, bytes(out))


def snmp_sysdescr_request():
    oid = encode_oid([1, 3, 6, 1, 2, 1, 1, 1, 0])
    varbind = ber(0x30, oid + ber(0x05, b""))
    varbind_list = ber(0x30, varbind)
    pdu = ber(0xa0, ber_integer(1) + ber_integer(0) + ber_integer(0) + varbind_list)
    return ber(0x30, ber_integer(0) + ber(0x04, b"public") + pdu)


def interact_snmp(port):
    request = snmp_sysdescr_request()
    result = {"protocol": "SNMP", "port": port,
              "operation": "one SNMPv1 sysDescr.0 GET using the conventional read-only community public",
              "credential_source": "single conventional community value; no task-supplied credentials were available",
              "request_hex": request.hex()}
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
            sock.settimeout(2.0)
            sock.sendto(request, (TARGET, port))
            response, peer = sock.recvfrom(65535)
        text = response.decode("utf-8", errors="replace")
        result.update({"status": "response_received", "peer": [peer[0], peer[1]],
                       "response_hex": response.hex(), "response_text_lossy": text,
                       "flag_matches": re.findall(r"(?i)flag\{[^}\r\n]{1,256}\}", text)})
    except socket.timeout:
        result.update({"status": "timeout", "limitation": "no SNMP response to this request"})
    except Exception as exc:
        result.update({"status": "error", "error": repr(exc)})
    return result


def main():
    ranges = [(start, min(start + BATCH_SIZE - 1, PORT_MAX))
              for start in range(PORT_MIN, PORT_MAX + 1, BATCH_SIZE)]
    results = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=WORKERS) as pool:
        futures = [pool.submit(scan_batch, start, end) for start, end in ranges]
        for future in concurrent.futures.as_completed(futures):
            results.append(future.result())
    results.sort(key=lambda item: int(item["range"].split("-")[0]))

    parsed = []
    for result in results:
        # Retain and emit each original framework envelope, including raw streams.
        emit({"batch": result["range"], "expected_ports": result["expected_ports"],
              "tool_envelope": result.get("envelope"),
              "helper_error": result.get("helper_error")})
        parsed.append(parse_batch(result))

    identified = [service for batch in parsed for service in batch["identified_services"]]
    summary = {
        "target": TARGET,
        "excluded_target_contacted": False,
        "requested_udp_ports": [PORT_MIN, PORT_MAX],
        "batch_size": BATCH_SIZE,
        "parallel_workers": WORKERS,
        "batch_count": len(parsed),
        "batch_coverage": parsed,
        "total_ports_accounted_for_by_nmap_states": sum(b["covered_ports"] for b in parsed),
        "all_batches_coverage_complete": all(b["coverage_complete"] for b in parsed),
        "identified_services": identified,
        "protocol_interactions": []
    }
    snmp_ports = sorted({s["port"] for s in identified
                         if (s.get("name") or "").lower() == "snmp"})
    for port in snmp_ports:
        summary["protocol_interactions"].append(interact_snmp(port))
    if not snmp_ports:
        summary["interaction_note"] = (
            "No probed SNMP service was identified, so no SNMP request was sent. "
            "Other service-specific login interactions require an actually identified protocol."
        )
    emit(summary)


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        emit({"status": "fatal_error", "error": repr(exc)})
        sys.exit(1)

