import ipaddress
import json
import re

import framework_evidence

NETWORK = ipaddress.ip_network("192.168.0.0/16")
EXCLUDED = {"192.168.0.1", "192.168.122.1"}
ARGV = [
    "nmap", "-sn", "-n", "-T4", "--min-rate", "1000", "--max-retries", "1",
    "--reason", "--exclude", ",".join(sorted(EXCLUDED)), str(NETWORK)
]


def main():
    report = {
        "operation": "parallel Nmap host discovery",
        "scope": str(NETWORK),
        "excluded_addresses": sorted(EXCLUDED),
        "command": ARGV,
        "coverage_note": "The requested range is not evidence of completed coverage; use the raw Nmap completion summary and execution status below.",
        "responsive_addresses": [],
        "responsive_address_parse_status": "unknown",
        "nmap_completion_summary": None,
        "coverage_parse_status": "unknown",
        "execution": None,
        "error": None,
    }
    try:
        result = framework_evidence.run_tool(ARGV)
        report["execution"] = result
        stdout = result.get("stdout") if isinstance(result, dict) else None
        if isinstance(stdout, str):
            found = []
            for match in re.finditer(r"^Nmap scan report for ([^\s]+)\s*$", stdout, re.MULTILINE):
                candidate = match.group(1)
                try:
                    addr = ipaddress.ip_address(candidate)
                except ValueError:
                    continue
                if addr in NETWORK and candidate not in EXCLUDED:
                    found.append(str(addr))
            report["responsive_addresses"] = sorted(set(found), key=ipaddress.ip_address)
            report["responsive_address_parse_status"] = "parsed_stdout" if stdout else "no_stdout"

            summary = re.search(r"^Nmap done: (.+)$", stdout, re.MULTILINE)
            if summary:
                report["nmap_completion_summary"] = summary.group(1)
                report["coverage_parse_status"] = "parsed_nmap_done_line"
            else:
                report["coverage_parse_status"] = "completion_summary_not_found"
        else:
            report["responsive_address_parse_status"] = "stdout_missing_or_non_string"
            report["coverage_parse_status"] = "stdout_missing_or_non_string"
    except Exception as exc:
        report["error"] = {"type": type(exc).__name__, "message": str(exc)}
        report["responsive_address_parse_status"] = "not_parsed_due_to_execution_error"
        report["coverage_parse_status"] = "unknown_due_to_execution_error"
    print(json.dumps(report, sort_keys=True))


if __name__ == "__main__":
    main()

