import concurrent.futures
import json
import sys

import framework_evidence

TARGET = "192.168.3.3"
RANGES = [(start, start + 1023) for start in range(1, 8193, 1024)]


def scan(port_range):
    start, end = port_range
    argv = [
        "nmap", "-n", "-Pn", "-sU", "-sV", "--version-light",
        "-T5", "--min-rate", "1000", "--max-retries", "1",
        "--host-timeout", "105s", "--reason", "-p", f"U:{start}-{end}",
        TARGET,
    ]
    try:
        envelope = framework_evidence.run_tool(argv)
    except Exception as exc:
        envelope = {
            "status": "tool_wrapper_error",
            "command": argv,
            "error": f"{type(exc).__name__}: {exc}",
        }
    return {"requested_udp_range": [start, end], "tool_envelope": envelope}


def main():
    results = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=8) as executor:
        futures = [executor.submit(scan, port_range) for port_range in RANGES]
        for future in concurrent.futures.as_completed(futures):
            try:
                results.append(future.result())
            except Exception as exc:
                results.append({
                    "status": "worker_error",
                    "error": f"{type(exc).__name__}: {exc}",
                })

    results.sort(key=lambda item: item.get("requested_udp_range", [99999])[0])
    report = {
        "target": TARGET,
        "protocol": "udp",
        "requested_port_coverage": [[start, end] for start, end in RANGES],
        "parallel_workers": 8,
        "coverage_note": (
            "These are requested ranges, not a claim of completed port coverage. "
            "Use each raw Nmap output, status, and structured observation to assess "
            "what was actually examined; timeout, filtered, omitted, or unparsed "
            "ports are not negative findings."
        ),
        "scans": results,
    }
    print(json.dumps(report, sort_keys=True))


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        print(json.dumps({
            "status": "script_error",
            "error": f"{type(exc).__name__}: {exc}",
        }, sort_keys=True))
        sys.exit(1)
